dir C:\Windows\Prefetch\*.pf /O-D
# วิเคราะห์ด้วย PECmd (MIT)
PECmd.exe -d C:\Windows\Prefetch --csv {OUT}

# ShimCache อยู่ใน SYSTEM hive
AppCompatCacheParser.exe -f C:\Windows\System32\config\SYSTEM --csv {OUT}
# AmCache เป็น hive แยก
AmcacheParser.exe -f C:\Windows\AppCompat\Programs\Amcache.hve --csv {OUT}

wevtutil qe Microsoft-Windows-Sysmon/Operational /q:"*[System[(EventID=2)]]" /f:text /c:30 /rd:true
# เทียบ $STANDARD_INFORMATION กับ $FILE_NAME ด้วย MFTECmd
MFTECmd.exe -f C:\$MFT --csv {OUT}
